/// <summary>
///     Data provider class for <c>AVASalesOrderDelegationReport</c> SSRS report
/// </summary>
/// <remarks>
///     This is the Data provider class for the <c>AVASalesOrderDelegationReport</c> SSRS Report.
/// </remarks>
[
    //SRSReportQueryAttribute(queryStr(AVASalesOrderDelegationReportDPQuery)),
    SRSReportParameterAttribute(classStr(AVASalesOrderDelegationReportContract))
]
class AVASalesOrderDelegationReportDP extends SrsReportDataProviderPreProcess //SRSReportDataProviderBase
{
    AVASalesOrderDelegationReportHeaderTmp  clsHeaderTmp;
    AVASalesOrderDelegationReportHeaderTmp  clsHeaderTmpBase;
    AVASalesOrderDelegationReportDetailTmp  clsDetailTmp;
    AVASalesOrderDelegationReportDetailTmp  clsDetailTmpBase;
    AVASalesOrderDelegationReportMarkupTmp  clsMarkupTmp;
    AVASalesOrderDelegationReportNoteTmp    clsNoteTmp;

    CompanyInfo                             clsCompanyInfo;
    CompanyImage                            clsCompanyLogo;
    Bitmap                                  clsCompanyLogoBitmap;
    container                               clsAllBPCompanies;

    SysDocuBrandDetails                     clsSysDocuBrandDetails;

    SalesTable                              clsSalesTable;
    SalesLine                               clsSalesLine;
    KCS_SOCSalesTableInfoFields             clsKCS_SOCSalesTableInfoFields;

    AVASalesOrderDelegationReportContract   clsReportContract;
    RefRecId                                clsSalesTableRecId;
    SalesId                                 clsSalesId;
    SalesTotals                             clsSalesTotals;
    MarkupValue                             clsMarkupValueSum;

    UnitOfMeasure                           clsUnitOfMeasure;
    UnitOfMeasureConverter_Product          clsUnitOfMeasureConverter_Product;

    int                                     clsAdditionalInfoLevel;

}

