/// <summary>
///     AVA <c>initialize</c> method.
/// </summary>
/// <remarks>
///     This method can be overridden by application developers to add any initialization logic needed.
///     This method is invoked by framework before <c>processReport</c> report is invoked.
/// </remarks>
public void initialize()
{
    this.setContractAndParamValues();
}

/// <summary>
///     AVA <c>processReport</c> method.
/// </summary>
public void processReport()
{
    Query                   locQuery;
    QueryBuildDataSource    locQueryBuildDataSource;
    QueryRun                locQueryRun;
    QueryBuildRange         locQueryBuildRange;

    //locQuery = this.parmQuery();
    locQuery                = new Query();
    locQueryBuildDataSource = locQuery.addDataSource(tableNum(SalesTable));

    if (clsSalesId)
    {
        locQueryBuildRange = locQuery.dataSourceTable(tableNum(SalesTable)).addRange(fieldNum(SalesTable, SalesId));
        locQueryBuildRange.value(SysQuery::value(clsSalesId));
    }

    locQueryRun    = new queryRun(locQuery);

    ttsbegin;
    while (locQueryRun.next())
    {
        clsSalesTable  = locQueryRun.get(tableNum(SalesTable));
        // insert data
        if(clsSalesTable.RecId)
        {
            this.insertTmpTableData();
        }
    }
    ttscommit;
}

/// <summary>
///     Gets the full data from the <c>AVASalesOrderDelegationReportHeaderTmp</c> temporary table.
/// </summary>
/// <returns>
///     The <c>AVASalesOrderDelegationReportHeaderTmp</c> temporary table.
/// </returns>
[SRSReportDataSetAttribute(tableStr(AVASalesOrderDelegationReportHeaderTmp))]
public AVASalesOrderDelegationReportHeaderTmp getHeaderTmp()
{
    AVASalesOrderDelegationReportHeaderTmp locTmpTable;

    this.setTransactionConnection(locTmpTable);

    select locTmpTable;

    return locTmpTable;
}

