/// <summary>
///     Set the database transaction connection for a record from the connection associated with the report.
/// </summary>
/// <param name = "_reportRecord">
///     A record to set database transaction for.
/// </param>
final protected void setTransactionConnection(Common _reportRecord)
{
    var connection = this.parmUserConnection();

    if (connection)
    {
        _reportRecord.setConnection(connection);
    }
}

    /// <summary>
    ///     AVA <c>processReport</c> method.
    /// </summary>
    public void setContractAndParamValues()
    {
        clsCompanyInfo          = CompanyInfo::find();
        clsCompanyLogo          = CompanyImage::findByRecord(clsCompanyInfo);
        clsCompanyLogoBitmap    = clsCompanyLogo.Image;
        clsAllBPCompanies       = AVAKBVBuildingProjectHelper::getAllBPCompanies();
        clsSysDocuBrandDetails  = SysDocuBrandDetails::getBrandDocument(this.parmDocuBrandContract());

        clsReportContract       = this.parmDataContract() as AVASalesOrderDelegationReportContract;

        clsSalesTableRecId      = clsReportContract.parmSalesTableRefRecId();
        clsSalesId              = clsReportContract.parmSalesId();

        clsUnitOfMeasure = UnitOfMeasure::findByInternalCode(UnitOfMeasureCodeSymbol::Pieces);
        if (!clsUnitOfMeasure)
        {
            checkFailed(strFmt("@GLS222805", UnitOfMeasureCodeSymbol::Pieces));
        }
        clsUnitOfMeasureConverter_Product   = UnitOfMeasureConverter_Product::construct();
}

/// <summary>
///     AVA <c>convertToPieces</c> method.
/// </summary>
/// <param name="_salesLine">
///    <c>SalesLine</c> as type
/// </param>
/// <returns>
///    <c>SalesQty</c> as return value
/// </returns>
public SalesQty convertToPieces(SalesLine _salesLine) 
{
    SalesQty retVal;

    if(     clsUnitOfMeasure.RecId
        &&  UnitOfMeasure::unitOfMeasureIdBySymbol(_salesLine.SalesUnit) != clsUnitOfMeasure.RecId  )
    {
        clsUnitOfMeasureConverter_Product.parmProduct(InventTable::find(_salesLine.ItemId).Product);
        clsUnitOfMeasureConverter_Product.parmFromUnitOfMeasure(UnitOfMeasure::unitOfMeasureIdBySymbol(_salesLine.SalesUnit));
        clsUnitOfMeasureConverter_Product.parmToUnitOfMeasure(clsUnitOfMeasure.RecId);
        clsUnitOfMeasureConverter_Product.parmRoundAbsoluteValue(NoYes::No);
        clsUnitOfMeasureConverter_Product.parmApplyRounding(NoYes::No);

        if(!clsUnitOfMeasureConverter_Product.avaConvertValueCheck())
        {
            warning(strFmt("@SYS342634", _salesLine.LineNum, _salesLine.ItemId));
        }

        retVal = clsUnitOfMeasureConverter_Product.convertValue(clsSalesLine.SalesQty);
    }
    return retVal;
}

/// <summary>
///     AVA <c>insertTmpTableData</c> method.
/// </summary>
public void insertTmpTableData()
{
    ttsbegin;
    if(clsSalesTable.RecId)
    {
        clsMarkupValueSum   = 0.0;
        clsSalesTotals      = SalesTotals::construct(clsSalesTable);
        clsSalesTotals.calc();
        // Header infos
        this.insertTmpTableDataHeader();
        if(clsReportContract.parmPrintMode() == SalesTableMode::Advanced)
        {
            this.insertTmpTableDataHeaderMarkups();
        }
        this.insertTmpTableDataHeaderNotes();
        // Detail infos
        this.insertTmpTableDataDetails();
        if(clsReportContract.parmPrintMode() == SalesTableMode::Advanced)
        {
            this.insertTmpTableDataHeaderTotal();
        }
    }
    ttscommit;
}

/// <summary>
///    AVA <c>initHeaderTmp</c> method.
/// </summary>
/// <param name="_avaReportLineType">
///    <c>AVAReportLineType</c> as type
/// </param>
/// <param name="_additionalInfoNo">
///    <c>int</c> as type
/// </param>
public void initHeaderTmp(  AVAReportLineType   _avaReportLineType  = AVAReportLineType::HeaderLine, 
                            int                 _additionalInfoNo   = 0                             )
{
    clsAdditionalInfoLevel                  = _additionalInfoNo;

    this.setTransactionConnection(clsHeaderTmp);

    clsHeaderTmp.clear();
    clsHeaderTmp.AVAReportLineType          = _avaReportLineType;
    clsHeaderTmp.AdditionalInfoNo           = clsAdditionalInfoLevel;

    clsHeaderTmp.SalesId                    = clsSalesTable.SalesId;
    clsHeaderTmp.HeaderRecId                = clsSalesTable.RecId;
}

