/// <summary>
///    AVA <c>insertTmpTableDataHeader</c> method.
/// </summary>
public void insertTmpTableDataHeader()
{
    FreeTxt                     locFreeTxt;
    CustTable                   locCustTableCust;
    CustTable                   locCustTableInvoice;
    LogisticsPostalAddress      locLogisticsPostalAddressCust;
    LogisticsPostalAddress      locLogisticsPostalAddressInvoice;
    LogisticsPostalAddress      locLogisticsPostalAddressDelivery;
    HcmWorker                   locHCMWorkerSalesResponsible;
    DirPerson                   locHCMWorkerSalesResponsibleDirPerson;
    HcmWorker                   locHCMWorkerSalesTaker;
    DirPerson                   locHCMWorkerSalesTakerDirPerson;
    ContactPerson               locContactPerson;
    DirPerson                   locContactPersonDirPerson;
    InventSite                  locInventSite;
    LogisticsPostalAddress      locLogisticsPostalAddressInventSite;

    locFreeTxt = '';

    if(clsSalesTable.RecId)
    {
        this.initHeaderTmp(AVAReportLineType::HeaderLine, 0);

        clsHeaderTmp.CompanyLogo                        = clsCompanyLogoBitmap;
        clsHeaderTmp.CompanyGroupLogo                   = clsSysDocuBrandDetails.Image1;
        clsHeaderTmp.CompanyNotesLine1                  = clsSysDocuBrandDetails.NotesLine1;
        clsHeaderTmp.CompanyPromotionImage              = clsSysDocuBrandDetails.Image2;
        clsHeaderTmp.CompanyNotesLine2                  = clsSysDocuBrandDetails.NotesLine2;
        clsHeaderTmp.CompanyFooterImage                 = clsSysDocuBrandDetails.Image3;
        clsHeaderTmp.CompanyNotesLine3                  = clsSysDocuBrandDetails.NotesLine3;
        clsHeaderTmp.CompanyAddressLine                 = clsSysDocuBrandDetails.AVASender;
        clsHeaderTmp.CompanyPostalAddressing            = clsCompanyInfo.postalAddress().Address;
        clsHeaderTmp.CompanyPostalAddressingSingleLine  = AVAHelperClass::adress2singleLineFormat('', clsHeaderTmp.CompanyPostalAddressing);

        clsHeaderTmp.AVADelegationDateTime              = clsSalesTable.AVADelegationDateTime;
        clsHeaderTmp.HeaderTxt                          = strFmt(   SysLabel::labelId2String2("@NDX:NXAOfSalesOrderNoP1FromP2", clsSalesTable.LanguageId),
                                                                    clsSalesTable.SalesId,
                                                                    DateTimeUtil::date(clsSalesTable.AVADelegationDateTime));
        clsHeaderTmp.SalesName                  = clsSalesTable.SalesName;
        clsHeaderTmp.CustAccount                = clsSalesTable.CustAccount;            //@SYS24704
        clsHeaderTmp.CustAccountCustName        = clsSalesTable.customerName();
        if(clsSalesTable.CustAccount)
        {
            locCustTableCust                            = clsSalesTable.custTable_CustAccount();
            locLogisticsPostalAddressCust               = locCustTableCust.postalAddress();
            if(locLogisticsPostalAddressCust.RecId)
            {
                clsHeaderTmp.CustAccountCustNames       = locLogisticsPostalAddressCust.NDXLogisticsLocationName1;
                if(clsHeaderTmp.CustAccountCustNames && locLogisticsPostalAddressCust.NDXLogisticsLocationName2)
                {
                    clsHeaderTmp.CustAccountCustNames   += '\n';
                }
                clsHeaderTmp.CustAccountCustNames       += locLogisticsPostalAddressCust.NDXLogisticsLocationName2;
                if(clsHeaderTmp.CustAccountCustNames && locLogisticsPostalAddressCust.NDXLogisticsLocationName3)
                {
                    clsHeaderTmp.CustAccountCustNames   += '\n';
                }
                clsHeaderTmp.CustAccountCustNames       += locLogisticsPostalAddressCust.NDXLogisticsLocationName3;
            }
        }
        clsHeaderTmp.InvoiceAccount             = clsSalesTable.InvoiceAccount;
        clsHeaderTmp.InvoiceAccountCustName     = clsSalesTable.invoiceName();
        if(clsSalesTable.InvoiceAccount)
        {
            locCustTableInvoice                             = clsSalesTable.custTable_InvoiceAccount();
            locLogisticsPostalAddressInvoice                = locCustTableInvoice.postalAddress();
            if(locLogisticsPostalAddressInvoice.RecId)
            {
                clsHeaderTmp.InvoiceAccountCustNames        = locLogisticsPostalAddressInvoice.NDXLogisticsLocationName1;
                if(clsHeaderTmp.InvoiceAccountCustNames && locLogisticsPostalAddressInvoice.NDXLogisticsLocationName2)
                {
                    clsHeaderTmp.InvoiceAccountCustNames    += '\n';
                }
                clsHeaderTmp.InvoiceAccountCustNames        += locLogisticsPostalAddressInvoice.NDXLogisticsLocationName2;
                if(clsHeaderTmp.InvoiceAccountCustNames && locLogisticsPostalAddressInvoice.NDXLogisticsLocationName3)
                {
                    clsHeaderTmp.InvoiceAccountCustNames    += '\n';
                }
                clsHeaderTmp.InvoiceAccountCustNames        += locLogisticsPostalAddressInvoice.NDXLogisticsLocationName3;
            }
        }

        clsHeaderTmp.SalesGroup                 = clsSalesTable.SalesGroup;             //@SYS23784
        clsHeaderTmp.PurchOrderFormNum          = clsSalesTable.PurchOrderFormNum;      //@NDX:CustMaterialOrder
        clsHeaderTmp.KCS_PurchRefDate           = clsSalesTable.KCS_PurchRefDate;       //@NDX:PurchRefDate - EDIOrderDate
        clsHeaderTmp.CustomerRef                = clsSalesTable.CustomerRef;            //@SYS23010
        clsHeaderTmp.DEL_KCS_CustShipDateReq    = clsSalesTable.DEL_KCS_CustShipDateReq;//@SYS88230
        clsHeaderTmp.ShippingDateRequested      = clsSalesTable.ShippingDateRequested ; //@SYS88230
        clsHeaderTmp.AVAEDIHeaderStatus         = clsSalesTable.AVAEDIHeaderStatus;     //@AVAEDI:EDI312
        if(clsSalesTable.WorkerSalesTaker)
        {
            clsHeaderTmp.WorkerSalesTaker           = clsSalesTable.WorkerSalesTaker;       //@SYS310060
            locHCMWorkerSalesTaker                  = HcmWorker::find(clsSalesTable.WorkerSalesTaker); //@SYS320666
            locHCMWorkerSalesTakerDirPerson         = locHCMWorkerSalesTaker.DirPerson();
            clsHeaderTmp.WorkerSalesTakerEmail      = locHCMWorkerSalesTakerDirPerson.availablEmail();
            if(!clsHeaderTmp.WorkerSalesTakerEmail)
            {
                clsHeaderTmp.WorkerSalesTakerEmail  = locHCMWorkerSalesTaker.email();
            }
            clsHeaderTmp.WorkerSalesTakerMobile     = locHCMWorkerSalesTakerDirPerson.availableMobile();
            //clsHeaderTmp.WorkerSalesTakerName       = locHCMWorkerSalesTaker.name();
            //clsHeaderTmp.WorkerSalesTakerName       = locHCMWorkerSalesTaker.displayAVAGetNameWithTitle();
            clsHeaderTmp.WorkerSalesTakerName       = locHCMWorkerSalesTakerDirPerson.avaGetNameWithTitle(clsSalesTable.LanguageId);
            clsHeaderTmp.WorkerSalesTakerPhone      = locHCMWorkerSalesTakerDirPerson.availablePhone();
            if(!clsHeaderTmp.WorkerSalesTakerPhone)
            {
                clsHeaderTmp.WorkerSalesTakerPhone  = locHCMWorkerSalesTaker.phone();
            }
            clsHeaderTmp.WorkerSalesTakerTeleFax    = locHCMWorkerSalesTakerDirPerson.AVAgetAvailableLogisticsElectronicAddressLocator(LogisticsElectronicAddressMethodType::Fax);
        }
        if(clsSalesTable.WorkerSalesResponsible)
        {
            clsHeaderTmp.WorkerSalesResponsible             = clsSalesTable.WorkerSalesResponsible;       //@SYS310060
            locHCMWorkerSalesResponsible                    = HcmWorker::find(clsSalesTable.WorkerSalesResponsible); //@SYS320666
            locHCMWorkerSalesResponsibleDirPerson           = locHCMWorkerSalesResponsible.DirPerson();
            clsHeaderTmp.WorkerSalesResponsibleEmail        = locHCMWorkerSalesResponsibleDirPerson.availablEmail();
            if(!clsHeaderTmp.WorkerSalesResponsibleEmail)
            {
                clsHeaderTmp.WorkerSalesResponsibleEmail    = locHCMWorkerSalesResponsible.email();
            }
            clsHeaderTmp.WorkerSalesResponsibleMobile       = locHCMWorkerSalesResponsibleDirPerson.availableMobile();
            //clsHeaderTmp.WorkerSalesResponsibleName         = locHCMWorkerSalesResponsible.name();
            //clsHeaderTmp.WorkerSalesResponsibleName         = locHCMWorkerSalesResponsible.displayAVAGetNameWithTitle();
            clsHeaderTmp.WorkerSalesResponsibleName         = locHCMWorkerSalesResponsibleDirPerson.avaGetNameWithTitle(clsSalesTable.LanguageId);
            clsHeaderTmp.WorkerSalesResponsiblePhone        = locHCMWorkerSalesResponsibleDirPerson.availablePhone();
            if(!clsHeaderTmp.WorkerSalesResponsiblePhone)
            {
                clsHeaderTmp.WorkerSalesResponsiblePhone    = locHCMWorkerSalesResponsible.phone();
            }
            clsHeaderTmp.WorkerSalesResponsibleTeleFax      = locHCMWorkerSalesResponsibleDirPerson.AVAgetAvailableLogisticsElectronicAddressLocator(LogisticsElectronicAddressMethodType::Fax);
        }
        /* contact person replacment
        if(clsSalesTable.ContactPersonId)
        {
            clsHeaderTmp.ContactPersonId                    = clsSalesTable.ContactPersonId;
            locContactPerson                                = ContactPerson::find(clsHeaderTmp.ContactPersonId);
            if(locContactPerson.RecId)
            {
                locContactPersonDirPerson                   = locContactPerson.getPerson();
                clsHeaderTmp.ContactPerson                  = locContactPerson.RecId;

                clsHeaderTmp.ContactPersonEmail             = locContactPersonDirPerson.availablEmail();
                clsHeaderTmp.ContactPersonMobile            = locContactPersonDirPerson.availableMobile();
                // clsHeaderTmp.ContactPersonName     = clsSalesTable.displayAVAContactPersonName();
                clsHeaderTmp.ContactPersonName              = ContactPerson::avaGetContactNameWithTitle(clsHeaderTmp.ContactPersonId,
                                                                                                        clsSalesTable.LanguageId);
                clsHeaderTmp.ContactPersonPhone             = locContactPersonDirPerson.availablePhone();
                clsHeaderTmp.ContactPersonTeleFax           = locContactPersonDirPerson.AVAgetAvailableLogisticsElectronicAddressLocator(LogisticsElectronicAddressMethodType::Fax);
            }
        }
        */
        clsHeaderTmp.ContactPersonName                      = clsSalesTable.AVAShipCarrierDeliveryContact;
        clsHeaderTmp.ContactPersonPhone                     = clsSalesTable.NDX_ShipCarrierDeliveryPhone;
        clsHeaderTmp.ContactPersonMobile                    = clsSalesTable.AVAShipCarrierDeliveryMobile;
        clsHeaderTmp.ContactPersonEmail                     = clsSalesTable.NDX_ShipCarrierDeliveryEmail;
        clsHeaderTmp.ContactPersonTeleFax                   = clsSalesTable.NDX_ShipCarrierDeliveryFax;

        if(clsHeaderTmp.ContactPersonTeleFax)
        {
            clsHeaderTmp.ContactPersonTeleFaxLine   = '@@+FAX:' + strKeep(clsHeaderTmp.ContactPersonTeleFax, '+0123456789') + '@@';
        }

        locInventSite = InventSite::find(clsSalesTable.InventSiteId);
        if(locInventSite.RecId)
        {
            clsHeaderTmp.InventSiteName                     = locInventSite.Name;                   // Agent name?   @SYS103211 Standort
            //locInventSite.AVAAgentSite;
            locLogisticsPostalAddressInventSite             = LogisticsLocationEntity::findPostalAddress(locInventSite, LogisticsLocationRoleType::Delivery);

            if(locLogisticsPostalAddressInventSite.RecId)
            {
                clsHeaderTmp.InventSiteLogisticsAddressing  = locLogisticsPostalAddressInventSite.Address;
                clsHeaderTmp.InventSiteNames                = locLogisticsPostalAddressInventSite.NDXLogisticsLocationName1;
                if(clsHeaderTmp.InventSiteNames && locLogisticsPostalAddressInventSite.NDXLogisticsLocationName2)
                {
                    clsHeaderTmp.InventSiteNames            += '\n';
                }
                clsHeaderTmp.InventSiteNames                += locLogisticsPostalAddressInventSite.NDXLogisticsLocationName2;
                if(clsHeaderTmp.InventSiteNames && locLogisticsPostalAddressInventSite.NDXLogisticsLocationName3)
                {
                    clsHeaderTmp.InventSiteNames            += '\n';
                }
                clsHeaderTmp.InventSiteNames                += locLogisticsPostalAddressInventSite.NDXLogisticsLocationName3;
            }                
            if(!clsHeaderTmp.InventSiteLogisticsAddressing)
            {
                clsHeaderTmp.InventSiteLogisticsAddressing  = locInventSite.logisticsPostalAddress().Address;
            }
        }
        if(clsSalesTable.DlvMode)
        {
            clsHeaderTmp.DlvMode                = clsSalesTable.DlvMode;                //@SYS210
            locFreeTxt                          = DlvMode::txt(clsSalesTable.DlvMode);
            if(!locFreeTxt)
            {
                locFreeTxt                      =  clsSalesTable.DlvMode;
            }
            clsHeaderTmp.DlvModeTxt             = locFreeTxt;
        }
        if(clsSalesTable.DlvTerm)
        {
            clsHeaderTmp.DlvTerm                = clsSalesTable.DlvTerm;                //@SYS6576
            locFreeTxt                          = DlvTerm::txt(clsSalesTable.DlvTerm);
            if(!locFreeTxt)
            {
                locFreeTxt                      =  clsSalesTable.DlvTerm;
            }
            clsHeaderTmp.DlvTermTxt             = locFreeTxt;
        }
        /* no Payment info needed
        if(clsSalesTable.Payment)
        {
            clsHeaderTmp.PaymTerm               = clsSalesTable.Payment;                //@SYS23346
            locFreeTxt                          = PaymTerm::txt(clsSalesTable.Payment);
            if(!locFreeTxt)
            {
                locFreeTxt                      =  clsSalesTable.Payment;
            }
            clsHeaderTmp.PaymTermTxt            = locFreeTxt;
        }
        */
        clsHeaderTmp.CashDisc                   = clsSalesTable.CashDisc;               //@SYS4376
        clsHeaderTmp.TaxGroup                   = clsSalesTable.TaxGroup;               //@SYS21919
        clsHeaderTmp.CurrencyCode               = clsSalesTable.CurrencyCode;           //@SYS7572
        clsHeaderTmp.DeliveryAddress            = clsSalesTable.deliveryAddressing();   //@SYS7924
        locLogisticsPostalAddressDelivery       = clsSalesTable.deliveryAddress();
        if(locLogisticsPostalAddressDelivery.RecId)
        {
            clsHeaderTmp.DeliveryAccountNames        = locLogisticsPostalAddressDelivery.NDXLogisticsLocationName1;
            if(clsHeaderTmp.DeliveryAccountNames && locLogisticsPostalAddressDelivery.NDXLogisticsLocationName2)
            {
                clsHeaderTmp.DeliveryAccountNames    += '\n';
            }
            clsHeaderTmp.DeliveryAccountNames        += locLogisticsPostalAddressDelivery.NDXLogisticsLocationName2;
            if(clsHeaderTmp.DeliveryAccountNames && locLogisticsPostalAddressDelivery.NDXLogisticsLocationName3)
            {
                clsHeaderTmp.DeliveryAccountNames    += '\n';
            }
            clsHeaderTmp.DeliveryAccountNames        += locLogisticsPostalAddressDelivery.NDXLogisticsLocationName3;
        }
        clsHeaderTmp.InvoiceAddress             = clsSalesTable.custTable_InvoiceAccount().address(); //@SYS58074
        clsHeaderTmp.ShipCarrierDeliveryContact = clsSalesTable.ShipCarrierDeliveryContact; //@SYS116731
        clsHeaderTmp.LogisticsAddressing = '';
        if(     clsHeaderTmp.LogisticsAddressing
            &&  clsSalesTable.AVAShipCarrierDeliveryContact )
        {
            clsHeaderTmp.LogisticsAddressing    += '\n';
        }
        if(clsSalesTable.AVAShipCarrierDeliveryContact)
        {
            clsHeaderTmp.LogisticsAddressing    += clsSalesTable.AVAShipCarrierDeliveryContact;
        }
        if(     clsHeaderTmp.LogisticsAddressing
            &&  clsSalesTable.NDX_ShipCarrierDeliveryPhone  )
        {
            clsHeaderTmp.LogisticsAddressing    += '\n';
        }
        if(clsSalesTable.NDX_ShipCarrierDeliveryPhone)
        {
            clsHeaderTmp.LogisticsAddressing    += strFmt("@SYS82282", "@NDX:ShipCarrierDeliveryPhone") + ': ' + clsSalesTable.NDX_ShipCarrierDeliveryPhone;
        }
        if(     clsHeaderTmp.LogisticsAddressing
            &&  clsSalesTable.AVAShipCarrierDeliveryMobile  )
        {
            clsHeaderTmp.LogisticsAddressing    += '\n';
        }
        if(clsSalesTable.AVAShipCarrierDeliveryMobile)
        {
            clsHeaderTmp.LogisticsAddressing    += strFmt("@SYS82282", "@SYS27784") + ': ' + clsSalesTable.AVAShipCarrierDeliveryMobile;
        }
        if(     clsHeaderTmp.LogisticsAddressing
            &&  clsSalesTable.NDX_ShipCarrierDeliveryEmail  )
        {
            clsHeaderTmp.LogisticsAddressing    += '\n';
        }
        if(clsSalesTable.NDX_ShipCarrierDeliveryEmail)
        {
            clsHeaderTmp.LogisticsAddressing    += strFmt("@SYS82282", "@NDX:ShipCarrierDeliveryEmail") + ': ' + clsSalesTable.NDX_ShipCarrierDeliveryEmail;
        }
        clsHeaderTmp.insert();

        clsHeaderTmpBase.clear();
        Buf2Buf(clsHeaderTmp, clsHeaderTmpBase);
        if(clsHeaderTmp.RecId)
        {
            //this.insertTmpTableDataHeaderInfos();
        }
    }
}

/// <summary>
///    AVA <c>insertTmpTableDataHeaderInfos</c> method.
/// </summary>
public void insertTmpTableDataHeaderInfos()
{
    clsKCS_SOCSalesTableInfoFields = KCS_SOCSalesTableInfoFields::find(AVATableInfoFieldTypes::Sales, clsSalesTable.SalesId);

    if(clsKCS_SOCSalesTableInfoFields.RecId)
    {
        this.initNoteTmp(AVAReportLineType::HeaderNotePre, 100);

        // Info 1
        clsNoteTmp.AdditionalInfoNo     = clsAdditionalInfoLevel;
        clsNoteTmp.Notes                = clsKCS_SOCSalesTableInfoFields.InfoField1;
        clsNoteTmp.insert();
        clsAdditionalInfoLevel++;
        // Info 2
        clsNoteTmp.AdditionalInfoNo     = clsAdditionalInfoLevel;
        clsNoteTmp.Notes                = clsKCS_SOCSalesTableInfoFields.InfoField2;
        clsNoteTmp.insert();
        clsAdditionalInfoLevel++;
    }
}

/// <summary>
///    AVA <c>insertTmpTableDataHeaderMarkups</c> method.
/// </summary>
void insertTmpTableDataHeaderMarkups()
{
    MarkupTrans locMarkupTrans;
    MarkupValue locMarkupValue;
    //MarkupValue locMarkupValueSum;
    container   locDisplayFields;

    this.initMarkupTmp(AVAReportLineType::HeaderMarkup, 200);

    while select locMarkupTrans
    where   locMarkupTrans.TransTableId == clsSalesTable.TableId 
        &&  locMarkupTrans.TransRecId   == clsSalesTable.RecId
        &&  !locMarkupTrans.IsDeleted
    {
        clsMarkupTmp.AdditionalInfoNo   = clsAdditionalInfoLevel;

        clsMarkupTmp.TransTableId       = locMarkupTrans.TransTableId;
        clsMarkupTmp.TransRecId         = locMarkupTrans.TransRecId;
        clsMarkupTmp.ModuleType         = locMarkupTrans.ModuleType;
        clsMarkupTmp.MarkupCategory     = locMarkupTrans.MarkupCategory;
        clsMarkupTmp.MarkupCode         = locMarkupTrans.MarkupCode;
        clsMarkupTmp.LineNum            = locMarkupTrans.LineNum;

        if(     locMarkupTrans.MarkupCategory == MarkupCategory::Percent 
            ||  locMarkupTrans.MarkupCategory == MarkupCategory::InterCompanyPercent)
        {
            clsMarkupTmp.Txt            = strfmt("%1 (%2%):", locMarkupTrans.Txt, locMarkupTrans.Value);
        }
        clsMarkupTmp.Txt                = locMarkupTrans.Txt + ':';

        if(     locMarkupTrans.MarkupCategory == MarkupCategory::Percent 
            ||  locMarkupTrans.MarkupCategory == MarkupCategory::InterCompanyPercent)
        {
            locDisplayFields = clsSalesTotals.displayFields();
            locMarkupValue          =  conpeek(locDisplayFields, TradeTotals::posBalance()) * (locMarkupTrans.Value / 100);
        }
        else
        {
            locMarkupValue          =  locMarkupTrans.Value;
        }
        clsMarkupValueSum               += locMarkupValue;
        clsMarkupTmp.Value              = locMarkupValue;
        clsMarkupTmp.CalculatedAmount   = locMarkupTrans.CalculatedAmount;
        clsMarkupTmp.AVACalcQty         = locMarkupTrans.AVACalcQty;

        clsMarkupTmp.insert();
        clsAdditionalInfoLevel++;
    }

    // build sum
    clsMarkupTmp.AVAReportLineType  = AVAReportLineType::DetailMarkupSum;
    clsMarkupTmp.Txt                = strFmt("@SYS82282", "@NDX:NXAChargesTotal") + ': ';
    clsMarkupTmp.Value              = clsMarkupValueSum;
    clsMarkupTmp.insert();
}

