        while select locDocuRef
        where  locDocuRef.RefTableId    == tableNum(SalesTable)
            && locDocuRef.RefRecId      == clsSalesTable.RecId
            && locDocuRef.Restriction   == DocuRestriction::External
            && locDocuRef.TypeId        == CustFormletterDocument::find().DocuTypeConfirm
        {
        /*
        while (locDocuRefSearch.next())
        {
            locDocuRef = locDocuRefSearch.docuRef();
            */
            if (locDocuRef.Notes)
            {
                clsNoteTmp.AdditionalInfoNo     = clsAdditionalInfoLevel;

                clsNoteTmp.RefTableId           = locDocuRef.refTableId;
                clsNoteTmp.RefRecId             = locDocuRef.RefRecId;
                clsNoteTmp.Name                 = locDocuRef.Name;
                clsNoteTmp.Notes                = locDocuRef.Notes;
                clsNoteTmp.Restriction          = locDocuRef.Restriction;
                clsNoteTmp.AVAFormat            = locDocuRef.AVAFormat;

                clsNoteTmp.insert();
                clsAdditionalInfoLevel++;
            }
        }
    }
}

/// <summary>
///    AVA <c>insertTmpTableDataDetails</c> method.
/// </summary>
public void insertTmpTableDataDetails()
{
    AVAEDISalesLineOrig     locAVAEDISalesLineOrig;

    NDXModelNumberHandler   locNDXModelNumberHandler;
    int                     locAdditionalInfoLevelTmp;
    InventDim               locInventDim;

    locNDXModelNumberHandler = NDXModelNumberHandler::construct();

    this.initDetailTmp(AVAReportLineType::DetailLine, 400);

    while select clsSalesLine
    where   clsSalesLine.SalesId                == clsSalesTable.SalesId
        &&  clsSalesLine.AVAItemSetComponent    == NoYes::No
    {
        locAVAEDISalesLineOrig                      = clsSalesLine.avaEDISalesLineOrig();

        locAdditionalInfoLevelTmp                   = clsAdditionalInfoLevel;
        // insert notes before position
        this.insertTmpTableDataDetailNotes( clsSalesLine, 
                                            AVAReportLineType::DetailNotePre, 
                                            locAVAEDISalesLineOrig              );
        clsAdditionalInfoLevel                      = locAdditionalInfoLevelTmp;

        clsDetailTmp.clear();
        clsDetailTmp.AVAReportLineType              = AVAReportLineType::DetailLine;

        clsDetailTmp.AdditionalInfoNo               = clsAdditionalInfoLevel;
        clsDetailTmp.DetailRecId                    = clsSalesLine.RecId;
        clsDetailTmp.SalesId                        = clsSalesLine.SalesId;

        clsDetailTmp.LineNum                        = clsSalesLine.LineNum;
        clsDetailTmp.ItemId                         = clsSalesLine.ItemId; //@SYS12836
        clsDetailTmp.KCS_ModelNumber                = locNDXModelNumberHandler.nDXModelNumberFromItemId(clsSalesLine.ItemId); // ToDo: KCS_ModelNumber?     //@NDXBase:NDXModelNumber
        /*
        if (clsSalesLine.KCS_PRCBomTypeId == KCS_PRCBomType::Case3)
        {
            return salesLine.KCS_PRCSortimentSalesQty;
        }
        else
        {
            return salesLine.SalesQty;
        }
        */
        clsDetailTmp.SalesQty                       = clsSalesLine.SalesQty;    //@SYS105177
        clsDetailTmp.SalesUnit                      = clsSalesLine.SalesUnit;   //@SYS190813
        if(     clsUnitOfMeasure.RecId
            &&  UnitOfMeasure::unitOfMeasureIdBySymbol(clsSalesLine.SalesUnit) == clsUnitOfMeasure.RecId    )
        {
            // already pieces
            clsDetailTmp.UnitQty                    = clsSalesLine.SalesQty;
        }
        else
        {
            clsDetailTmp.UnitQty                    = this.convertToPieces(clsSalesLine);                   //@NDX:NXAPieces  ToDo: convert to pieces?
        }
        clsDetailTmp.AVASpecialDiscountSalesPrice   = clsSalesLine.displayAVASalesPriceRebateIncluded();    //@NDX:NXAAVASpecialDiscountSalesPrice       ToDo: 2009 salesLine.KCS_RebatedPrice()
        clsDetailTmp.AVASpecialDiscountPct1         = clsSalesLine.displayAVASpecialDiscSalesLineSP1();     //@NDX:NXAAVASpecialDiscountPercent1                                                     //2009 KCS_SOCSalesLineManualDisc::find(clsSalesLine.InventTransId).LineDiscPct1;
        clsDetailTmp.AVASpecialDiscountPct2         = clsSalesLine.displayAVASpecialDiscSalesLineSP2();     //@NDX:NXAAVASpecialDiscountPercent2
        clsDetailTmp.AVASpecialDiscountPct3         = clsSalesLine.displayAVASpecialDiscSalesLineSP3();
        clsDetailTmp.AVASpecialDiscountPct4         = clsSalesLine.displayAVASpecialDiscSalesLineSP4();
        clsDetailTmp.AVASpecialDiscountPct5         = clsSalesLine.displayAVASpecialDiscSalesLineSP5();
        clsDetailTmp.AVASpecialDiscountPct6         = clsSalesLine.displayAVASpecialDiscSalesLineSP6();
        clsDetailTmp.AVASpecialDiscountPct7         = clsSalesLine.displayAVASpecialDiscSalesLineSP7();
        clsDetailTmp.LineAmount                     = clsSalesLine.LineAmount;                              // ToDo: 2009 LineAmount dependant on  salesLine.KCS_PRCBomTypeId == KCS_PRCBomType::Case3
        clsDetailTmp.AVAQuotationId                 = clsSalesLine.AVAQuotationId;
        clsDetailTmp.AVAOrigQuotationId             = clsSalesLine.AVAOrigQuotationId;
        clsDetailTmp.AVAOrigQuotExpiredDate         = clsSalesLine.AVAOrigQuotExpiredDate();                //@SYS54367
        //ToDo: salesLine.KCS_EDIStatus missing
        clsDetailTmp.LineHeader                     = clsSalesLine.LineHeader;
        clsDetailTmp.Name                           = clsSalesLine.Name;
        clsDetailTmp.SalesPrice                     = clsSalesLine.SalesPrice;
        clsDetailTmp.SalesStatus                    = clsSalesLine.SalesStatus;
        clsDetailTmp.SalesType                      = clsSalesLine.SalesType;
        locInventDim = clsSalesLine.inventDim();
        if(     locInventDim.RecId
            &&  locInventDim.InventColorId)
        {
            clsDetailTmp.InventColorId              = locInventDim.InventColorId;
        }
        clsDetailTmp.AVAShippingDateRequested       = clsSalesLine.AVAShippingDateRequested;

        clsDetailTmp.insert();

        locAdditionalInfoLevelTmp                   = clsAdditionalInfoLevel;
        /*
        // insert markups of position
        this.insertTmpTableDataDetailMarkups(clsSalesLine);
        */
        // insert notes after position
        this.insertTmpTableDataDetailNotes( clsSalesLine, 
                                            AVAReportLineType::DetailNotePost,
                                            locAVAEDISalesLineOrig              );
        clsAdditionalInfoLevel                      = locAdditionalInfoLevelTmp;

        clsAdditionalInfoLevel++;
        // insert partitioner
        this.initDetailTmp(AVAReportLineType::Partitioner, clsAdditionalInfoLevel);
        clsDetailTmp.insert();
        clsAdditionalInfoLevel++;
    }
}

/// <summary>
///    AVA <c>insertTmpTableDataDetailMarkups</c> method.
/// </summary>
void insertTmpTableDataDetailMarkups(SalesLine _salesLine)
{
    MarkupTrans locMarkupTrans;
    MarkupValue locMarkupValue;
    MarkupValue locMarkupValueSum;
    int         locMarkupPositions;

    clsAdditionalInfoLevel = 500;

    this.setTransactionConnection(clsMarkupTmp);

    clsMarkupTmp.clear();
    clsMarkupTmp.AVAReportLineType  = AVAReportLineType::DetailMarkup;

    while select locMarkupTrans
    where   locMarkupTrans.TransTableId == _salesLine.TableId
        &&  locMarkupTrans.TransRecId   == _salesLine.RecId
        &&  !locMarkupTrans.IsDeleted
    {
        clsMarkupTmp.AdditionalInfoNo   = clsAdditionalInfoLevel;
        clsMarkupTmp.DetailRecId        = locMarkupTrans.RecId;
        clsMarkupTmp.SalesId            = _salesLine.SalesId;

        clsMarkupTmp.TransTableId       = locMarkupTrans.TransTableId;
        clsMarkupTmp.TransRecId         = locMarkupTrans.TransRecId;
        clsMarkupTmp.ModuleType         = locMarkupTrans.ModuleType;
        clsMarkupTmp.MarkupCategory     = locMarkupTrans.MarkupCategory;
        clsMarkupTmp.MarkupCode         = locMarkupTrans.MarkupCode;
        clsMarkupTmp.LineNum            = locMarkupTrans.LineNum;
        clsMarkupTmp.Txt                = locMarkupTrans.Txt;
        if(     locMarkupTrans.MarkupCategory == MarkupCategory::Percent 
            ||  locMarkupTrans.MarkupCategory == MarkupCategory::InterCompanyPercent)
        {
            locMarkupValue              = _salesLine.LineAmount * (locMarkupTrans.Value / 100);
        }
        else if(locMarkupTrans.MarkupCategory == MarkupCategory::Pcs)
        {
            locMarkupValue              = _salesLine.QtyOrdered * locMarkupTrans.Value;
        }
        else
        {
            locMarkupValue = locMarkupTrans.Value;
        }
        locMarkupValueSum += locMarkupValue;

        clsMarkupTmp.Value              = locMarkupTrans.Value;
        clsMarkupTmp.CalculatedAmount   = locMarkupTrans.CalculatedAmount;
        clsMarkupTmp.AVACalcQty         = locMarkupTrans.AVACalcQty;

        clsMarkupTmp.insert();

        clsDetailTmp.AVAReportLineType  = clsMarkupTmp.AVAReportLineType;
        clsDetailTmp.MarkupCode         = locMarkupTrans.MarkupCode;
        clsDetailTmp.MarkupTxt          = locMarkupTrans.Txt;
        clsDetailTmp.MarkupLineAmount   = locMarkupValue;
        clsDetailTmp.insert();
        locMarkupPositions++;
        clsAdditionalInfoLevel++;
    }
    // build sum
    if(locMarkupPositions)
    {
        clsDetailTmp.AVAReportLineType  = AVAReportLineType::DetailMarkupSum;
        clsDetailTmp.MarkupTxt          = strFmt("@SYS82282", "@SYS22995") + ': ';
        clsDetailTmp.MarkupLineAmount   = locMarkupValueSum;
        clsDetailTmp.insert();
    }
}

