                clsDetailTmp.insert();
                clsAdditionalInfoLevel++;
            }
        }
    }
}

/// <summary>
///    AVA <c>insertTmpTableDataDetailNotes</c> method.
/// </summary>
void insertTmpTableDataHeaderTotal()
{
    container locDisplayFields;

    this.initDetailTmp(AVAReportLineType::HeaderSum, 700);

    clsDetailTmp.DetailRecId        = clsSalesTable.RecId;

    clsDetailTmp.AdditionalInfoNo   = clsAdditionalInfoLevel;
    locDisplayFields                = clsSalesTotals.displayFields();
    clsDetailTmp.LineAmount         = conpeek(locDisplayFields, TradeTotals::posTotalAmount()) - conpeek(locDisplayFields, TradeTotals::posTaxTotal());
    // add header markups to total
    //clsDetailTmp.LineAmount         += clsMarkupValueSum;
    clsDetailTmp.insert();
    clsAdditionalInfoLevel++;
}
